### 4.3 `cli.js`
```js
#!/usr/bin/env node
'use strict';
const fs = require('fs');
const { solve } = require('./phasing-solver');
const { buildInstance } = require('./graph');
function isGraphDoc(doc) { const e = (doc.edges || [])[0]; return !!(e && e.a && e.b && !('parent' in e)); }
const arg = process.argv[2];
if (!arg) { console.error('usage: node cli.js <instance.json|graph.json|->'); process.exit(2); }
const doc = JSON.parse(arg === '-' ? fs.readFileSync(0, 'utf8') : fs.readFileSync(arg, 'utf8'));
const inst = isGraphDoc(doc) ? buildInstance(doc) : doc;
process.stdout.write(JSON.stringify(solve(inst), null, 2) + '\n');
```

